\newcommand{\rankgroup}{\mathbb Z\times_{\mathrm{lex}}(\mathbb Z\times_{\mathrm{lex}}\mathbb Z)}
\newcommand{\supp}{\operatorname{supp}}
\newcommand{\ord}{\operatorname{ord}}

\title{Integer-Ranked Hahn Transseries:\\Unique Asymptotic Comparison, a Real-Closedness Obstruction,\\and the Limits of Pointwise Semantics}
\author{Aristotle}
\date{July 31, 2026}

\begin{document}
\maketitle

\begin{abstract}
We study a Hahn-series model for finite-level transseries with real coefficients and lexicographically ordered integer growth ranks $\Gamma=\rankgroup$. Three claims often bundled into broad transseries programs are separated. Every unequal pair of series has a unique first rank at which its coefficients differ. In contrast, the field is not real closed: the monomial at rank $(1,0,0)$ and its negative are both nonsquares, because a nonzero square has twice the order of its root. Finally, evaluation of raw exponential--logarithmic expressions at one point is not injective: the variable and constant zero coincide at zero. We give algorithms for finite representations and formulate corrected programs based on divisible value groups and eventual germs at $+\infty$.
\end{abstract}

\section{Introduction}
Ordinary power series resolve local behavior into successively ordered powers. Transseries pursue the analogous goal for scales containing powers, logarithms, exponentials, and their iterations. This ambition raises distinct questions: whether formal expansions admit exact comparison, whether the ambient field is real closed, and whether an expansion or sampled value determines the expression from which it arose.

We investigate these questions for real-coefficient Hahn series indexed by $\Gamma=\rankgroup$. The three coordinates can represent successive growth levels; the proofs use only their ordered-group structure. The conclusions are sharply divided. Well-ordered support gives a canonical first disagreement between unequal series. Integer ranks, however, are not divisible, and the rank $(1,0,0)$ cannot be the order of a square. Moreover, a point value cannot identify raw syntax.

This separation suggests precise repairs. Real closedness calls for a divisible value group, initially a rational lexicographic group. Semantic uniqueness calls for controlled domains, normalization, and eventual germs rather than raw syntax or isolated values.

\section{Ranks and Hahn transseries}

\begin{definition}[Lexicographic growth rank]
Let $\Gamma=\mathbb Z^3$ as an additive group. For $\alpha=(a_1,a_2,a_3)$ and $\beta=(b_1,b_2,b_3)$, set $\alpha<\beta$ when the first coordinate at which they differ is smaller in $\alpha$. We write this ordered group as $\rankgroup$.
\end{definition}

The order is total and translation invariant. The group is not divisible: no integer triple $\delta$ satisfies $2\delta=(1,0,0)$.

\begin{definition}[Hahn transseries]
A Hahn transseries over $\Gamma$ is a formal sum
\[
 F=\sum_{\gamma\in\Gamma}a_\gamma t^\gamma,
\]
where $a_\gamma\in\mathbb R$ and $\supp(F)=\{\gamma:a_\gamma\ne0\}$ is well ordered. The coefficient at $\gamma$ is denoted $[t^\gamma]F$. Addition is coefficientwise and multiplication is determined by $t^\alpha t^\beta=t^{\alpha+\beta}$.
\end{definition}

A coefficient-$c$ monomial is $ct^\gamma$. Well-ordered support permits the following leading-rank definition.

\begin{definition}[Order]
For $F\ne0$, define
\[
 \ord(F)=\min\supp(F).
\]
\end{definition}

\begin{lemma}[Order of a product]\label{lem:product-order}
If $F$ and $G$ are nonzero Hahn transseries, then
\[
 \ord(FG)=\ord(F)+\ord(G).
\]
\end{lemma}
\begin{proof}
Put $\alpha=\ord(F)$ and $\beta=\ord(G)$. Every occupied rank of $F$ is at least $\alpha$, and every occupied rank of $G$ is at least $\beta$, so no product rank lies below $\alpha+\beta$. At $\alpha+\beta$, the product of the leading coefficients is nonzero and supplies the leading contribution. Thus $\alpha+\beta$ is the least occupied rank of $FG$.
\end{proof}

\begin{corollary}[Order of a square]\label{cor:square-order}
For every nonzero $F$,
\[
 \ord(F^2)=2\ord(F).
\]
\end{corollary}

\begin{definition}[Agreement below a rank]
Transseries $F$ and $G$ agree below $\rho\in\Gamma$ when
\[
 [t^\gamma]F=[t^\gamma]G\qquad\text{for every }\gamma<\rho.
\]
A first disagreement rank is a $\rho$ below which they agree and at which $[t^\rho]F\ne[t^\rho]G$.
\end{definition}

\section{Unique asymptotic comparison}

\begin{theorem}[Existence of a first disagreement]\label{thm:existence}
If $F\ne G$, there is a rank $\rho$ below which $F$ and $G$ agree and at which their coefficients differ.
\end{theorem}
\begin{proof}
The difference $H=F-G$ is nonzero, so its support is a nonempty well-ordered set. Let $\rho=\min\supp(H)$. Every coefficient of $H$ below $\rho$ is zero, while its coefficient at $\rho$ is nonzero. These statements are respectively agreement of $F,G$ below $\rho$ and disagreement at $\rho$.
\end{proof}

\begin{lemma}[Uniqueness of the disagreement rank]\label{lem:unique}
If $\rho$ and $\sigma$ are both first disagreement ranks for $F$ and $G$, then $\rho=\sigma$.
\end{lemma}
\begin{proof}
By trichotomy, either $\rho<\sigma$, $\rho=\sigma$, or $\sigma<\rho$. In the first case, agreement below $\sigma$ forces agreement at $\rho$, contradicting disagreement there. The third case is symmetric. Hence equality is the only possibility.
\end{proof}

\begin{theorem}[Unique First-Disagreement Theorem]\label{thm:first}
For every unequal pair $F\ne G$, there exists exactly one rank $\rho$ such that
\[
 [t^\gamma]F=[t^\gamma]G\quad(\gamma<\rho),
 \qquad [t^\rho]F\ne[t^\rho]G.
\]
\end{theorem}
\begin{proof}
Existence is Theorem~\ref{thm:existence}; uniqueness is Lemma~\ref{lem:unique}.
\end{proof}

\begin{corollary}[Coefficient identity principle]
If two Hahn transseries have equal coefficients at every rank, then they are equal.
\end{corollary}
\begin{proof}
Otherwise Theorem~\ref{thm:first} would supply a rank at which the coefficients differ.
\end{proof}

Thus an inequality has a canonical finite certificate: its least disagreement rank together with the two unequal coefficients. This is an exact series statement. An analytic identity theorem for functions additionally requires an interpretation of series as eventual germs.

\section{The real-closedness obstruction}

We use a standard necessary property: in a real closed field, at least one of $a$ and $-a$ is a square for every $a$. Indeed, one sign is nonnegative and every nonnegative element is a square.

Let $\omega=(1,0,0)$ and $M=t^\omega$.

\begin{lemma}[The odd rank is not doubled]\label{lem:odd}
There is no $\delta\in\Gamma$ with $2\delta=\omega$.
\end{lemma}
\begin{proof}
Writing $\delta=(d_1,d_2,d_3)$, equality in the first coordinate would give $2d_1=1$, impossible for an integer $d_1$.
\end{proof}

\begin{theorem}[Nonsquareness of the odd-rank monomial]\label{thm:positive}
The monomial $M=t^{(1,0,0)}$ is not a square.
\end{theorem}
\begin{proof}
If $M=F^2$, then $F\ne0$. Corollary~\ref{cor:square-order} gives
\[
 (1,0,0)=\ord(M)=\ord(F^2)=2\ord(F),
\]
contradicting Lemma~\ref{lem:odd}.
\end{proof}

\begin{theorem}[Nonsquareness of the negative monomial]\label{thm:negative}
The series $-M=-t^{(1,0,0)}$ is not a square.
\end{theorem}
\begin{proof}
Its order remains $(1,0,0)$ because its only coefficient is $-1\ne0$. A hypothetical equality $-M=F^2$ would again imply $(1,0,0)=2\ord(F)$, contrary to Lemma~\ref{lem:odd}.
\end{proof}

\begin{theorem}[Failure of real closedness]\label{thm:notrc}
The Hahn field with real coefficients and rank group $\rankgroup$ is not real closed.
\end{theorem}
\begin{proof}
If it were real closed, one of $M$ and $-M$ would be a square. Theorems~\ref{thm:positive} and~\ref{thm:negative} exclude both possibilities.
\end{proof}

The obstruction is specifically nondivisibility of the value group. Replacing $\Gamma$ by
\[
 \mathbb Q\times_{\mathrm{lex}}(\mathbb Q\times_{\mathrm{lex}}\mathbb Q)
\]
removes this parity barrier since $(1,0,0)=2(1/2,0,0)$. A positive real-closedness result still requires the full Hahn-field theorem with a real closed coefficient field and divisible value group.

\section{Point evaluation and corrected semantics}

Consider a raw expression language containing real constants and a variable $x$, possibly together with arithmetic, logarithms, and exponentials. Distinct syntax trees remain distinct even when they represent the same function.

\begin{proposition}[Point evaluation is not injective]\label{prop:evaluation}
The map sending an expression $E$ to $E(0)$ is not injective.
\end{proposition}
\begin{proof}
The variable expression $x$ and constant expression $0$ are distinct, but both evaluate to zero at $x=0$.
\end{proof}

Richer languages contain further semantic identities from commutativity, associativity, and domain-dependent exponential--logarithmic cancellation. Hence uniqueness should not target raw syntax.

\begin{definition}[Eventual equality and germs]
Functions $f$ and $g$ are eventually equal at $+\infty$ if some $A\in\mathbb R$ satisfies $f(x)=g(x)$ for every $x>A$ where both are defined. An eventual germ is an equivalence class under this relation.
\end{definition}

A corrected expansion theorem should choose a domain-controlled language, pass to eventual germs, define a normalized expansion map, prove that it respects addition and multiplication, and show that its kernel is exactly eventual equality to zero. Injectivity may then be sought on a normalized summable fragment.

\section{Algorithms and examples}

\subsection{First-disagreement search}
For finite supports, represent a series as a map from integer triples to nonzero real coefficients. Form the union of ranks, sort it lexicographically, and scan until coefficients differ. For $n$ occupied ranks, this requires $O(n\log n)$ comparisons and $O(n)$ storage. If the inputs are ordered maps, a merge scan takes $O(n)$ time.

Correctness follows directly: all earlier ranks in the union have equal coefficients, omitted ranks have zero coefficient in both series, and the returned rank differs. Theorem~\ref{thm:first} makes the result canonical.

For example, with
\[
 F=3t^{(0,0,0)}+2t^{(1,0,0)}-t^{(1,1,0)},\qquad
 G=3t^{(0,0,0)}+5t^{(1,0,0)}-t^{(1,1,0)},
\]
the first disagreement is $(1,0,0)$. Later agreement cannot erase this earliest difference.

\subsection{Square-order screening}
A necessary condition for $ct^{(g_1,g_2,g_3)}$ to be a square is that every $g_i$ be even. Testing parity costs constant time in this three-level model and $O(d)$ in dimension $d$. An odd coordinate is a conclusive nonsquareness certificate. Even coordinates merely produce a candidate half-rank and do not settle coefficient or higher-term constraints.

Thus $(1,0,0)$ and $(0,3,0)$ fail immediately, while $(2,-4,6)=2(1,-2,3)$ passes the order-level test.

\subsection{Evaluation collisions}
For finitely many expressions, evaluate at a chosen input and group by value. Any group containing distinct syntax trees witnesses noninjectivity. At zero, $x$, $0$, and $x^2$ all collide, although at $2$ their values are $2$, $0$, and $4$.

\section{Applications}
The first-disagreement theorem supports interpretable certificates in symbolic asymptotics. A normal-form engine can report not only that expansions differ but also the earliest scale and coefficients responsible. In approximation pipelines, this rank locates the first term requiring investigation.

The real-closedness obstruction guides model design. Systems requiring algebraic closure properties cannot assume that integer-ranked transseries contain all relevant square roots. The odd-rank monomial is an explicit regression test against such an assumption.

The semantic counterexample is relevant to symbolic expression discovery. Isolated samples cannot identify syntax, and without restrictions they need not identify functions. A credible identification theorem needs canonical normal forms, a sampling theorem for a restricted family, or a quotient by semantic equivalence. Eventual germs align naturally with asymptotic applications.

\section{Analytic interpretation}
The comparison theorem is internal to generalized series. To connect it to analysis, one should define an interpretation into germs of real functions and prove four properties:
\begin{enumerate}[label=(\roman*)]
\item the leading nonzero monomial controls eventual sign;
\item lower-ranked terms are asymptotically negligible relative to higher-ranked terms under the chosen dominance convention;
\item interpretation is injective on a normalized summable fragment;
\item formal agreement at every rank implies equality of eventual germs.
\end{enumerate}

A staged program begins with polynomial--Laurent expressions, continues with one logarithmic level under positivity restrictions, and then adds one exponential level. At every stage the expansion should preserve ring operations and its kernel should be identified with eventual equality.

\section{Discussion and future directions}
The present results separate exact comparison, field closure, and expression semantics. The model has only three growth coordinates and does not yet encode arbitrary exponential and logarithmic towers. The nonsquareness argument identifies a decisive obstruction but does not classify every square. Point-evaluation failure concerns raw syntax and does not rule out identification in a normalized restricted class.

For broader growth hierarchies, one may use finitely supported rational-valued maps on a well-ordered set of levels, ordered to match asymptotic dominance. Divisibility then avoids the elementary parity obstruction. On the semantic side, controlled logarithm domains and eventual equality are essential. On the computational side, sparse ordered maps provide linear-time comparison once supports are sorted.

\section{Conclusion}
Every unequal pair in the integer-ranked Hahn field has a unique first disagreement rank, giving exact asymptotic comparison and a canonical witness of inequality. Nevertheless, the monomial at $(1,0,0)$ and its negative are both nonsquares, so this field is not real closed. Point evaluation also fails to identify raw expressions. These conclusions indicate the correct architecture for further work: well-ordered support for comparison, divisible rank groups for real-closed models, and normalized eventual germs for semantic uniqueness.

